1299-replace-elements-with-greatest-elem:
/**
 * Reverse - Space O(1)
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/replace-elements-with-greatest-element-on-right-side/
 * @param {number[]} arr
 * @return {number[]}
 */
var replaceElements = (arr, max = -1, ans = [ -1 ]) => {
    arr = arr.reverse();                          /* Time O(N) */

    for (let i = 0; (i < (arr.length - 1)); i++) {/* Time O(N) */
        max = Math.max(max, arr[i]);
        ans[(i + 1)] = max;                           /* Space O(N) */
    }

    return ans.reverse();                         /* Time O(N) */
};

/**
 * Backward - In-Place
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/replace-elements-with-greatest-element-on-right-side/
 * @param {number[]} arr
 * @return {number[]}
 */
var replaceElements = (arr, max = -1) => {
     for (let i = (arr.length - 1); (0 <= i); i--) {/* Time O(N) */
         const num = arr[i];

         arr[i] = max;
         max = Math.max(max, num);
     }

     return arr;
};
//  This is brute force with O(n^2). Just for reference's sake.
// submission link: https://leetcode.com/problems/replace-elements-with-greatest-element-on-right-side/submissions/844439163/
var replaceElementsBrute = function(arr) {

    for(let i = 0; i < arr.length; i++) {
        arr[i] = biggestElement(i, arr);
    }

    arr[arr.length - 1] = -1;
    return arr;
};

function biggestElement(index, arr) {

    let biggest = 0;
    for(let i = index + 1; i < arr.length; i++) {
        biggest = Math.max(biggest, arr[i]);
    }

    return biggest;
}

0392-is-subsequence:
/**
 * Time O(N) | Space O(1)
 * @param {string} s
 * @param {string} t
 * @return {boolean}
 */
var isSubsequence = function (s, t) {
    if (!s.length || s === t) return true;
    if (s.length > t.length) return false;

    let j = 0;

    for (let i = 0; i < t.length && j < s.length; i++) {
        if (s[j] === t[i]) {
            j++;
        }
    }

    return j === s.length;
};

/**
 * Time O(N^2) | Space O(1)
 * @param {string} s
 * @param {string} t
 * @return {boolean}
 */
var isSubsequence = function (s, t) {
    for (let char of s) {
        let indexChar = t.indexOf(char);
        if (indexChar === -1) {
            return false;
        }
        t = t.slice(indexChar + 1);
    }
    return true;
};

0058-length-of-last-word:
/**
 * @param {string} s
 * @return {number}
 */
var lengthOfLastWord = function (s) {
    let len = 0;

    for (let i in s) {
        if (s[i] != ' ') {
            if (s[i - 1] == ' ') len = 1;
            else len += 1;
        }
    }
    return len;
};

// another approach. starting out from the last so we don't have to go all the way to the end.
var lengthOfLastWord = function (s) {
    let firstCharOccurance = false;
    let lastWordLen = 0;

    for (let i = s.length - 1; i > -1; i--) {
        if (s[i] !== ' ') {
            firstCharOccurance = true;
            lastWordLen++;
        }
        if (firstCharOccurance && s[i] === ' ') {
            break;
        }
    }
    return lastWordLen;
};

0001-two-sum:
/**
 * Brute Force - Linear Search
 * Time O(N^2) | Space O(1)
 * https://leetcode.com/problems/two-sum/
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = (nums, target) => {
    for (let curr = 0; curr < nums.length; curr++) {
        /* Time O(N) */
        const complement = target - nums[curr];

        for (let next = curr + 1; next < nums.length; next++) {
            /* Time O(N) */
            const num = nums[next];

            const isTarget = num === complement;
            if (isTarget) return [curr, next];
        }
    }

    return [-1, -1];
};

/**
 * Hash Map - 2 Pass
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/two-sum/
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = (nums, target) => {
    const map = getMap(nums); /* Time O(N) | Space O(N) */

    return getSum(nums, target, map); /* Time O(N) */
};

const getMap = (nums, map = new Map()) => {
    for (let index = 0; index < nums.length; index++) {
        /* Time O(N) */
        map.set(nums[index], index); /* Space O(N) */
    }

    return map;
};

const getSum = (nums, target, map) => {
    for (let index = 0; index < nums.length; index++) {
        /* Time O(N) */
        const complement = target - nums[index];
        const sumIndex = map.get(complement);

        const isTarget = map.has(complement) && map.get(complement) !== index;
        if (isTarget) return [index, sumIndex];
    }

    return [-1, -1];
};

/**
 * Hash Map - 1 Pass
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/two-sum/
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = (nums, target, map = new Map()) => {
    for (let index = 0; index < nums.length; index++) {
        /* Time O(N) */
        const num = nums[index];
        const complement = target - num;
        const sumIndex = map.get(complement);

        const isTarget = map.has(complement);
        if (isTarget) return [index, sumIndex];

        map.set(num, index); /* Space O(N) */
    }

    return [-1, -1];
};

0014-longest-common-prefix:
/**
 * Time O(N^2) | Space O(N)
 * @param {string[]} strs
 * @return {string}
 */
var longestCommonPrefix = function (strs) {
    let pre = strs[0];

    for (let word of strs) {
        for (let i = pre.length - 1; i >= 0; i--) {
            if (pre[i] !== word[i]) {
                pre = pre.slice(0, i);
            }
        }
    }

    return pre;
};

0049-group-anagrams:
/**
 * Sort - HeapSort Space O(1) | QuickSort Space O(log(K))
 * Hash Map - Adjacency List
 * Time O(N * (K * log(K))) | Space O(N * K)
 * https://leetcode.com/problems/group-anagrams/
 * @param {string[]} strs
 * @return {string[][]}
 */
var groupAnagrams = (words, map = new Map()) => {
    if (!words.length) return [];

    groupWords(words, map); /* Time O(N * (K * log(K)) | Space O(N * K) */

    return [...map.values()]; /* Time O(N)               | Space O(N * K) */
};

var groupWords = (words, map) => {
    for (const original of words) {
        /* Time O(N) */
        const sorted = reorder(original); /* Time O(K * log(K)) | Space O(K) */
        const values = map.get(sorted) || [];

        values.push(original); /*                    | Space O(N) */
        map.set(sorted, values); /*                    | Space O(N * K) */
    }
};

const reorder = (str) =>
    str
        .split('') /* Time O(K)          | Space O(K) */
        .sort((a, b) =>
            a.localeCompare(b),
        ) /* Time O(K * log(K)) | Space O(1 || log(K)) */
        .join(''); /* Time O(K)          | Space O(K) */

/**
 * Hash Map
 * Time O(N * K) | Space O(N * K)
 * https://leetcode.com/problems/group-anagrams/
 * @param {string[]} words
 * @return {string[][]}
 */
var groupAnagrams = (words, map = new Map()) => {
    if (!words.length) return [];

    groupWords(words, map); /* Time O(N * K) | Space O(N * K) */

    return [...map.values()]; /* Time O(N)     | Space O(N * K) */
};

var groupWords = (words, map) => {
    for (const original of words) {
        /* Time O(N) */
        const hash = getHash(original); /* Time O(K) | Space O(1) */
        const values = map.get(hash) || [];

        values.push(original); /*           | Space O(N) */
        map.set(hash, values); /*           | Space O(N * K) */
    }
};

const getHash = (word) => {
    const frequency = new Array(26).fill(0);

    for (const char of word) {
        /* Time O(K) */
        const charCode = getCode(char); /* Time O(1) | Space (1) */

        frequency[charCode]++; /*           | Space O(1) */
    }

    return buildHash(frequency);
};

const getCode = (char) => char.charCodeAt(0) - 'a'.charCodeAt(0);

const buildHash = (frequency) => frequency.toString();

0118-pascals-triangle:
// link to the problem https://leetcode.com/problems/pascals-triangle/
// the time complexity will basically be the number of elements in pascale tringle. roughly height of tringle * number of honeycomb in each row.
// O(n^2);

var generate = function (numRows) {
    const res = [[1]];

    for (let i = 1; i < numRows; i++) {
        res[i] = [];
        for (let k = 0; k < i + 1; k++) {
            res[i][k] = (res[i - 1][k] || 0) + (res[i - 1][k - 1] || 0);
        }
    }

    return res;
};

0027-remove-element:
/**
 * Time O(N) | Space O(1)
 * @param {number[]} nums
 * @param {number} val
 * @return {number}
 */
var removeElement = function (nums, val) {
    let ptr1 = nums.length - 2;
    let ptr2 = nums.length - 1;

    if (!nums) return 0;
    if (nums.length === 1) {
        if (nums[0] === val) return 0;
        return 1;
    }

    while (ptr1 > -1) {
        if (nums[ptr2] === val) {
            ptr2--;

            while (nums[ptr1] === val) {
                ptr2--;
                ptr1--;
            }
        } else if (nums[ptr1] === val) {
            let temp = nums[ptr1];
            nums[ptr1] = nums[ptr2];
            nums[ptr2] = temp;
            ptr2--;
        }

        ptr1--;
    }

    return ptr2 + 1;
};

/**
 * @param {number[]} nums
 * @param {number} val
 * @return {number}
 */
var removeElement = function (nums, val) {
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === val) {
            nums.splice(i, 1);
            i--;
        }
    }

    return nums.length;
};

0929-unique-email-addresses:
/**
 * Built-in Functions Solution
 * Hash Set - Unique Emails
 * Time O(N * K) | Space O(N)
 * https://leetcode.com/problems/unique-email-addresses
 * @param {string[]} emails
 * @return {number}
 */
var numUniqueEmails = function (emails) {
    const valid = emails.map((email) => {
        const [local, domain] = email.split('@');
        return local.split('+').shift().split('.').join('') + '@' + domain;
    });

    return new Set(valid).size;
};

/**
 * Manual Solution
 * Hash Set - Unique Emails
 * Time O(N * K) | Space O(N)
 * https://leetcode.com/problems/unique-email-addresses
 * @param {string[]} emails
 * @return {number}
 */
var numUniqueEmails = function (emails) {
    const uniqEmails = new Set();

    for (let email of emails) {
        let cleanEmail = '';
        for (let i = 0; i < email.length; i++) {
            if (email[i] === '@') {
                cleanEmail += email.slice(i);
                break;
            } else if (email[i] === '+') {
                while (email[i] !== '@') i++;
                cleanEmail += email.slice(i);
                break;
            } else if (email[i] !== '.') {
                cleanEmail += email[i];
            }
        }

        uniqEmails.add(cleanEmail);
    }

    return uniqEmails.size;
};

0205-isomorphic-strings:
var isIsomorphic = function (s, t) {
    if (s.length !== t.length) return false;

    const mapOne = new Map();
    const mapTwo = new Map();

    for (let i = 0; i < s.length; i++) {
        if (mapOne.has(s[i])) {
            if (mapOne.get(s[i]) !== t[i]) return false;
        } else mapOne.set(s[i], t[i]);

        if (mapTwo.has(t[i])) {
            if (mapTwo.get(t[i]) !== s[i]) return false;
        } else mapTwo.set(t[i], s[i]);
    }

    return true;
};

0605-can-place-flowers:
/**
 * Loop Solution
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/can-place-flowers
 * @param {number[]} fb
 * @param {number} n
 * @return {boolean}
 */

var canPlaceFlowers = function (fb, n) {
    if (n === 0) return true;

    for (let i = 0; i < fb.length; i++) {
        if (fb[i] === 0) {
            fb[i - 1] !== 1 && fb[i + 1] !== 1 && n-- && i++;
        } else {
            i++;
        }
        if (n === 0) return true;
    }

    return false;
};

0169-majority-element:
/**
 * Boyer Moore Algorithm
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/majority-element
 * @param {number[]} nums
 * @return {number}
 */

var majorityElement = function (nums) {
    let res = nums[0];
    let count = 1;

    for (let i = 1; i < nums.length - 1; i++) {
        if (nums[i] === res) count++;
        else if (!--count) {
            res = nums[i + 1];
            count = 0;
        }
    }

    return res;
};

/**
 * HashMap
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/majority-element
 * @param {number[]} nums
 * @return {number}
 */

var majorityElement = function (nums) {
    const occuranceOfElement = new Map();

    for (let i = 0; i < nums.length; i++) {
        if (occuranceOfElement.has(nums[i])) {
            let occurance = occuranceOfElement.get(nums[i]);
            occuranceOfElement.set(nums[i], occurance + 1);
        } else {
            occuranceOfElement.set(nums[i], 1);
        }
    }

    for (let [key, value] of occuranceOfElement) {
        if (value > nums.length / 2) return key;
    }
};

0496-next-greater-element-i:
/**
 * HashMap and Stack
 * Time O(N + M) | Space O(N)
 * https://leetcode.com/problems/next-greater-element-i
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number[]}
 */

var nextGreaterElement = function (nums1, nums2) {
    const subsetMap = new Map(nums1.map((val, i) => [val, i]));
    const res = new Array(nums1.length).fill(-1);

    let stack = [];

    for (let num of nums2) {
        while (stack.length && num > stack.at(-1)) {
            const val = stack.pop();
            const idx = subsetMap.get(val);
            res[idx] = num;
        }

        if (subsetMap.has(num)) stack.push(num);
    }

    return res;
};

0724-find-pivot-index:
/**
 * https://leetcode.com/problems/find-pivot-index/
 * @param {number[]} nums
 * @return {number}
 */
var pivotIndex = function (nums) {
    const totalSum = nums.reduce((sum, el) => {
        sum += el;
        return sum;
    }, 0);
    let pos = 0;
    let leftSum = 0;
    while (pos <= nums.length - 1) {
        if (leftSum === totalSum - nums[pos] - leftSum) {
            return pos;
        }
        leftSum += nums[pos];
        pos++;
    }
    return -1;
};

