var findDisappearedNumbers = function (nums) {
    for (let i = 0; i < nums.length; i++) {
        let curr = Math.abs(nums[i]);
        let idx = curr - 1;
        if (nums[idx] > 0) {
            nums[idx] = nums[idx] * -1;
        }
    }
    let res = [];
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] > 0) {
            res.push(i + 1);
        }
    }
    return res;
};

