0912-sort-an-array:
/**
 * https://leetcode.com/problems/sort-an-array/
 * Merge Sort
 * Time O(n*log(n)) | Space O(n)
 * @param {number[]} nums
 * @return {number[]}
 */
const sortArray = function (nums) {
    return mergeSort(0, nums.length - 1, nums);
};

const mergeSort = (left, right, nums) => {
    if (left === right) return nums;

    const mid = Math.floor((left + right) / 2);
    mergeSort(left, mid, nums);
    mergeSort(mid + 1, right, nums);
    return merge(left, right, mid, nums);
};

const merge = (left, right, mid, nums) => {
    const arr1 = nums.slice(left, mid + 1);
    const arr2 = nums.slice(mid + 1, right + 1);

    let p1 = 0;
    let p2 = 0;
    let gp = left;

    while (p1 < arr1.length && p2 < arr2.length) {
        if (arr1[p1] < arr2[p2]) {
            nums[gp] = arr1[p1];
            p1++;
        } else {
            nums[gp] = arr2[p2];
            p2++;
        }
        gp++;
    }

    while (p1 < arr1.length) {
        nums[gp] = arr1[p1];
        p1++;
        gp++;
    }

    while (p2 < arr2.length) {
        nums[gp] = arr2[p2];
        p2++;
        gp++;
    }
    return nums;
};

0347-top-k-frequent-elements:
/**
 * Set - Frequency Counter | Using sort
 * Time O(NlogN) | Space O(N)
 * https://leetcode.com/problems/top-k-frequent-elements/
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var topKFrequent = function (nums, k) {
    let frequency = {};
    for (let i = 0; i < nums.length; i++) {
        if (frequency.hasOwnProperty(nums[i])) frequency[nums[i]] += 1;
        else frequency[nums[i]] = 1;
    }
    let result = Object.keys(frequency).map((key) => [
        Number(key),
        frequency[key],
    ]);
    let sortedResult = result.sort((a, b) => {
        return b[1] - a[1];
    });
    let output = [];
    for (let i = 0; i < k; i++) {
        output.push(sortedResult[i][0]);
    }
    return output;
};

/**
 * Without Sort
 * Time O(N) | Space O(k)
 * https://leetcode.com/problems/top-k-frequent-elements/
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */

var topKFrequent = function (nums, k) {
    const mp = new Map();
    const arr = new Array(nums.length + 1).fill(0);
    const ans = [];

    nums.forEach((el) => {
        const val = mp.get(el) || 0;
        mp.set(el, val + 1);
    });

    for (let [key, value] of mp) {
        const prev = arr[value] || [];
        prev.push(key);
        arr[value] = prev;
    }

    arr.reverse();
    for (let el of arr) {
        if (k < 1) break;
        if (el) {
            for (let el2 of el) {
                ans.push(el2);
                k--;
            }
        }
    }

    return ans;
};

0238-product-of-array-except-self:
/**
 * Array
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/product-of-array-except-self/
 * @param {number[]} nums
 * @return {number[]}
 */
function productExceptSelf(nums) {
    const result = [];
    let prefix = 1;
    let postfix = 1;

    for (let i = 0; i < nums.length; i++) {
        result[i] = prefix;
        prefix *= nums[i];
    }
    for (let i = nums.length - 2; i >= 0; i--) {
        postfix *= nums[i + 1];
        result[i] *= postfix;
    }

    return result;
}

0036-valid-sudoku:
/**
 * Hash Map - Matrix
 * Time O(ROWS * COLS) | Space O(ROWS * COLS)
 * https://leetcode.com/problems/valid-sudoku/
 * @param {character[][]} board
 * @return {boolean}
 */

var isValidSudoku = function (board) {
    let row = [];
    let col = [];
    let squares = new Map();
    // Creating new col, row and sqaures Sets
    for (let i = 0; i < 9; i++) {
        let newRowSet = new Set();
        let newColSet = new Set();
        row.push(newRowSet);
        col.push(newColSet);
        for (let j = 0; j < 9; j++) {
            squares.set(`${Math.floor(i / 3)}:${Math.floor(j / 3)}`, new Set());
        }
    }

    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            if (board[i][j] === '.') {
                continue;
            }
            if (
                row[i].has(board[i][j]) ||
                col[j].has(board[i][j]) ||
                squares
                    .get(`${Math.floor(i / 3)}:${Math.floor(j / 3)}`)
                    .has(board[i][j])
            ) {
                return false;
            }
            row[i].add(board[i][j]);
            col[j].add(board[i][j]);
            squares
                .get(`${Math.floor(i / 3)}:${Math.floor(j / 3)}`)
                .add(board[i][j]);
        }
    }
    return true;
};

/**
 * Hash Map - Matrix
 * Time O(ROWS * COLS) | Space O(ROWS * COLS)
 * https://leetcode.com/problems/valid-sudoku/
 * @param {character[][]} board
 * @return {boolean}
 */
var isValidSudoku = (board) => {
    const boards = 3;
    const [boxes, cols, rows] =
        getBoards(boards); /* Time O(ROWS * COLS) | Space O(ROWS * COLS) */

    return searchGrid(
        board,
        boxes,
        cols,
        rows,
    ); /* Time O(ROWS * COLS) | Space O(ROWS * COLS) */
};

var initBoard = (rows, cols) =>
    new Array(rows).fill().map(() => new Array(cols).fill(false));

var getBoards = (boards) => {
    const [rows, cols] = [9, 9];

    return new Array(boards).fill().map(() => initBoard(rows, cols));
};

var searchGrid = (board, boxes, cols, rows) => {
    const [_rows, _cols] = [9, 9];

    for (let row = 0; row < _rows; row++) {
        /* Time O(ROWS)*/
        for (let col = 0; col < _cols; col++) {
            /* Time O(COLS)*/
            const char = board[row][col];
            const index = Math.floor(row / 3) * 3 + Math.floor(col / 3);

            const isEmpty = char === '.';
            if (isEmpty) continue;

            const hasMoved =
                boxes[index][char - 1] ||
                cols[col][char - 1] ||
                rows[row][char - 1];
            if (hasMoved) return false;

            rows[row][char - 1] = true; /* Space O(ROWS * COLS)*/
            cols[col][char - 1] = true; /* Space O(ROWS * COLS)*/
            boxes[index][char - 1] = true; /* Space O(ROWS * COLS)*/
        }
    }

    return true;
};

/**
 * Array - Fixed Size
 * Time O(ROWS * COLS) | Space O(CELLS)
 * https://leetcode.com/problems/valid-sudoku/
 * @param {character[][]} board
 * @return {boolean}
 */
var isValidSudoku = (board) => {
    const [boards, cells] = [3, 9];
    const [boxes, rows, cols] = getBoards(
        boards,
        cells,
    ); /* Time O(ROWS * COLS) | Space O(CELLS) */

    return searchGrid(
        board,
        boxes,
        rows,
        cols,
    ); /* Time O(ROWS * COLS) | Space O(CELLS) */
};

var getBoards = (boards, cells) =>
    new Array(boards).fill().map(() => new Array(cells).fill(0));

var searchGrid = (board, boxes, rows, cols) => {
    const [_rows, _cols] = [9, 9];

    for (let row = 0; row < _rows; row++) {
        /* Time O(ROWS)*/
        for (let col = 0; col < _cols; col++) {
            /* Time O(COLS)*/
            const char = board[row][col];
            const position = 1 << (char - 1);
            const index = Math.floor(row / 3) * 3 + Math.floor(col / 3);

            const isEmpty = char === '.';
            if (isEmpty) continue;

            const hasMoved =
                boxes[index] & position ||
                cols[col] & position ||
                rows[row] & position;
            if (hasMoved) return false;

            rows[row] |= position; /* Space O(CELLS)*/
            cols[col] |= position; /* Space O(CELLS)*/
            boxes[index] |= position; /* Space O(CELLS)*/
        }
    }

    return true;
};

