                    same[i][j]++;
                }
            }
        }
    }
    let res = 0;
    for (let i = 0; i < 26; i++) {
        for (let j = i + 1; j < 26; j++) {
            res +=
                (sets[i].size - same[i][j]) * (sets[j].size - same[i][j]) * 2;
