/**
 * BFS
 * Time O(n) | Space O(1)
 *
 * https://leetcode.com/problems/populating-next-right-pointers-in-each-node/
 * // Definition for a Node.
 * function Node(val, left, right, next) {
 *    this.val = val === undefined ? null : val;
 *    this.left = left === undefined ? null : left;
 *    this.right = right === undefined ? null : right;
 *    this.next = next === undefined ? null : next;
 * };
 */
/**
 * @param {Node} root
 * @return {Node}
 */

var connect = function (root) {
    let currentNode = root;
    let nextLevelNode = root && root.left;

    while (currentNode && nextLevelNode) {
        currentNode.left.next = currentNode.right;
        if (currentNode.next) {
            currentNode.right.next = currentNode.next.left;
        }
        currentNode = currentNode.next;
        if (!currentNode) {
            currentNode = nextLevelNode;
            nextLevelNode = currentNode.left;
        }
    }

    return root;
};

1268-search-suggestions-system:
/**
 * Binary Search
 *
 * Time O(n*log(n) + m*n) | Space O(m)
 * https://leetcode.com/problems/search-suggestions-system/description/
 * @param {string[]} products
 * @param {string} searchWord
 * @return {string[][]}
 */
var suggestedProducts = function (products, searchWord) {
    products.sort((product1, product2) => {
        if (product1 < product2) {
            return -1;
        }
        if (product2 < product1) {
            return 1;
        }
        if (product1 === product2) {
            return 0;
        }
    });

    const result = [];
    let left = 0;
    let right = products.length - 1;
    for (let i = 0; i < searchWord.length; i++) {
        let char = searchWord[i];

        while (
            left <= right &&
            (products[left].length - 1 < i || products[left][i] !== char)
        ) {
            left++;
        }
        while (
            left <= right &&
            (products[right].length - 1 < i || products[right][i] !== char)
        ) {
            right--;
        }

        const subResult = [];
        const len = Math.min(right - left + 1, 3);
        for (let j = 0; j < len; j++) {
            subResult.push(products[left + j]);
        }
        result.push(subResult);
    }

    return result;
};

/**
 * DFS - Trie
 * Time O(N * M) | Space O(N)
 * https://leetcode.com/problems/search-suggestions-system/
 * @param {string[]} products
 * @param {string} searchWord
 * @return {string[][]}
 */
var suggestedProducts1 = (products, searchWord) =>
    new Trie().buildTrie(products).searchWord(searchWord);

class Node {
    constructor() {
        this.children = new Map();
        this.isWord = false;
    }
}

class Trie {
    constructor() {
        this.root = new Node();
    }

    buildTrie(products) {
        for (const word of products) {
            this.insert(word);
        }

        return this;
    }

    insert(word, { root: node } = this) {
        for (const char of word.split('')) {
            const child = node.children.get(char) ?? new Node();

            node.children.set(char, child);

            node = child;
        }

        node.isWord = true;
    }

    searchWord(searchWord, buffer = [], suggestions = []) {
        for (const char of searchWord.split('')) {
            const prefix = this.getPrefix(buffer, char);
            const words = this.getSuggestions(prefix);

            suggestions.push(words);
        }

        return suggestions;
    }

    getPrefix(buffer, char) {
        buffer.push(char);

        return buffer.join('');
    }

    getSuggestions(prefix, words = []) {
        const node = this.getPrefixNode(prefix);

        const isInvalidPrefix = node === null;
        if (isInvalidPrefix) return words;

        return this.search(node, prefix, words);
    }

    getPrefixNode(prefix, { root: node } = this) {
        for (const char of prefix.split('')) {
            const child = node.children.get(char) ?? null;

            const isLeafNode = child === null;
            if (isLeafNode) return null;

            node = child;
        }

        return node;
    }

    search(node, word, words) {
        const isBaseCase = words.length === 3;
        if (isBaseCase) return words;

        if (node.isWord) words.push(word);

        return this.dfs(node, word, words);
    }

    dfs(node, word, words) {
        for (const char of this.getChars()) {
            const child = node.children.get(char) ?? null;

            const isLeafNode = child === null;
            if (isLeafNode) continue;

            this.search(child, word + char, words);
        }

        return words;
    }

    getChars() {
        return new Array(26)
            .fill()
            .map((_, index) => String.fromCharCode(index + 97));
    }
}

0410-split-array-largest-sum:
/**
 * https://leetcode.com/problems/split-array-largest-sum/
 *
 * Binary Search
 * Time O(log(s)*n) (s = difference between the least and max possible value) | Space O(1)
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var splitArray = function (nums, k) {
    let left = Math.max(...nums);
    let right = nums.reduce((acc, num) => acc + num, 0);
    let result = right;
    while (left <= right) {
        const mid = (left + right) >> 1;
        if (canSplit(mid)) {
            result = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    function canSplit(largest) {
        let splitCount = 0;
        let currSum = 0;

        for (let i = 0; i < nums.length; i++) {
            currSum += nums[i];
            if (currSum > largest) {
                currSum = nums[i];
                splitCount++;
            }
        }

        return splitCount + 1 <= k;
    }

    return result;
};

0004-median-of-two-sorted-arrays:
/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * Time O(log(N * M)) | Space O(N)
 * @return {number}
 */
var findMedianSortedArrays = function (nums1, nums2) {
    const canSwap = nums2.length < nums1.length;
    if (canSwap) [nums1, nums2] = [nums2, nums1];

    let [left, right] = [0, nums1.length - 1];
    const totalLength = nums1.length + nums2.length;
    const mid = totalLength >> 1;
    const isEven = totalLength % 2 === 0;

    while (true) {
        const mid1 = left + right;
        const mid2 = mid - mid1 - 2;
        const { aLeft, aRight, bLeft, bRight } = getPointers(
            nums1,
            mid1,
            nums2,
            mid2,
        );

        const isTarget = aLeft <= bRight && bLeft <= aRight;
        if (isTarget)
            return isEven
                ? (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2
                : Math.min(aRight, bRight);

        const isTargetGreater = aLeft <= bRight;
        if (isTargetGreater) left = mid1 + 1;

        const isTargetLess = bRight < aLeft;
        if (isTargetLess) right = mid1 - 1;
    }
};

const getPointers = (nums1, mid1, nums2, mid2) => {
    const getLeft = (nums, index) => (0 <= index ? nums[index] : -Infinity);

    const [aLeft, bLeft] = [getLeft(nums1, mid1), getLeft(nums2, mid2)];

    const getRight = (nums, index) =>
        index + 1 < nums.length ? nums[index + 1] : Infinity;

    const [aRight, bRight] = [getRight(nums1, mid1), getRight(nums2, mid2)];

    return { aLeft, aRight, bLeft, bRight };
};

