    while (leftPointer && rightPointer) {
        max = Math.max(leftPointer.val + rightPointer.val, max);
        leftPointer = leftPointer.next;
        rightPointer = rightPointer.next;
    }
    return max;
};
var getRightPointer = (head, mid) => {
    let count = 0;
    let rightPointer = head;
    while (count < mid) {
        rightPointer = rightPointer.next;
        count++;
    }
    return rightPointer;
};

var llLength = (head) => {
    let count = 0;
    while (head) {
        head = head.next;
        count++;
    }
    return count;
};

