        const isBaseBitSet = 0 < (i & mask);
        if (isBaseBitSet) baseCount++;

        const isNumBitSet = 0 < (nums[i] & mask);
        if (isNumBitSet) numsCount++;
    }

    return [baseCount, numsCount, mask];
};

/**
