        const [num, arrayIndex, arrayNum] = [
            nums[index],
            nums[index] - 1,
            nums[nums[index] - 1],
        ];

        const canSwap = !isSame(num, arrayNum);
        if (canSwap) {
            swap(nums, index, arrayIndex);

            continue;
        }

        index++;
    }
};
const isSame = (a, b) => a === b;

const search = (nums) => {
