    const root = new TreeNode(
        nums[mid],
    ); /*           | Ignore Auxillary Space O(N) */

    root.left = sortedArrayToBST(
        nums,
        left,
        mid - 1,
    ); /* Time O(N) | Space O(log(N)) */
    root.right = sortedArrayToBST(
        nums,
        mid + 1,
        right,
    ); /* Time O(N) | Space O(log(N)) */

    return root;
};

