/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Hashing
 * Time O(n^2) | Space O(n^2)
 * https://leetcode.com/problems/find-duplicate-subtrees/
 * @param {TreeNode} root
 * @return {TreeNode[]}
 */
var findDuplicateSubtrees = function (root) {
    const stringHash = {};

    const makePreOrderStr = (node, str) => {
        if (!node) return str + '-' + 'null';

        const str1 = makePreOrderStr(node.left, str + '-' + node.val);
        const str2 = makePreOrderStr(node.right, str1);

        return str2;
    };

    const duplicates = [];

    const dfs = (node) => {
        if (!node) return;
        const str = makePreOrderStr(node, '');

        if (!stringHash[str]) {
            stringHash[str] = [];
        }

        stringHash[str].push(node);

        dfs(node.left);
        dfs(node.right);
    };

    dfs(root);

    for (let key in stringHash) {
        if (stringHash[key].length > 1) duplicates.push(stringHash[key][0]);
    }

    return duplicates;
};

0958-check-completeness-of-a-binary-tree:
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Time O(n) | Space O(n)
 * LevelOrder traversal | BFS
 * https://leetcode.com/problems/check-completeness-of-a-binary-tree/
 * @param {TreeNode} root
 * @return {boolean}
 */
var isCompleteTree = function (root) {
    // get the depth of the tree
    // bfs until n-1 level of depth

    const getDepth = (node) => {
        if (!node) return 0;
        return 1 + Math.max(getDepth(node.left), getDepth(node.right));
    };

    const depth = getDepth(root) - 1;

    const q = new Queue();
    q.enqueue(root);

    const checkLastLevel = (arr) => {
        while (arr[arr.length - 1] === null) arr.pop();

        let i = 0;
        while (i < arr.length) {
            if (arr[i] === null) return false;
            i++;
        }

        return true;
    };

    let i = 0;
    while (i < depth) {
        let size = q.size();

        if (size !== 2 ** i) return false;

        while (size) {
            const node = q.dequeue();
            if (!node.left && i !== depth - 1) return false;
            if (!node.right && i !== depth - 1) return false;

            if (i !== depth - 1) {
                q.enqueue(node.left);
                q.enqueue(node.right);
            } else {
                if (!node.left) {
                    q.enqueue(null);
                } else {
                    q.enqueue(node.left);
                }

                if (!node.right) {
                    q.enqueue(null);
                } else {
                    q.enqueue(node.right);
                }
            }

            size--;
        }

        i++;
    }

    return checkLastLevel(q.toArray());
};

0106-construct-binary-tree-from-inorder-:
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * Recursion | Tree
 * Time O(n) | Space O(n)
 * https://leetcode.com/problems/construct-binary-tree-from-inorder-and-postorder-traversal/
 * @param {number[]} inorder
 * @param {number[]} postorder
 * @return {TreeNode}
 */
var buildTree = function (inorder, postorder) {
    let globleIdx = inorder.length - 1;

    const dfs = (start, end) => {
        if (start === end) {
            globleIdx--;
            return new TreeNode(inorder[start]);
        }

        if (start > end) return null;

        let i = start;

        while (i < end + 1) {
            if (inorder[i] === postorder[globleIdx]) break;
            i++;
        }

        globleIdx--;
        const currRoot = new TreeNode(inorder[i]);

        currRoot.right = dfs(i + 1, end);
        currRoot.left = dfs(start, i - 1);

        return currRoot;
    };

    return dfs(0, globleIdx);
};

