 * @param {TreeNode} root
 * @return {number}
 */
var rob = function (root) {
    function dfs(root) {
        if (!root) return [0, 0];

        const leftSubTree = dfs(root.left);
        const rightSubTree = dfs(root.right);

        const withoutRoot =
            Math.max(...leftSubTree) + Math.max(...rightSubTree);
