/**
 * https://leetcode.com/problems/task-scheduler/
 * Time O(N * log(N)) | Space O(N)
 * @param {character[]} tasks
 * @param {number} n
 * @return {number}
 */
var leastInterval = function (tasks, n) {
    const frequencyMap = getFrequencyMap(tasks);
    const maxHeap = getMaxHeap(frequencyMap);

    return getMinimumCpuIntervals(maxHeap, n);
};

var getFrequencyMap = (tasks, frequencyMap = new Array(26).fill(0)) => {
    for (const task of tasks) {
        const index = task.charCodeAt(0) - 'A'.charCodeAt(0);

        frequencyMap[index]++;
    }

    return frequencyMap;
};

const getMaxHeap = (frequencyMap, maxHeap = new MaxPriorityQueue()) => {
    for (const frequency of frequencyMap) {
        const hasFrequency = 0 < frequency;
        if (hasFrequency) maxHeap.enqueue(frequency);
    }

    return maxHeap;
};

const getMinimumCpuIntervals = (maxHeap, n, cpuIntervals = [0]) => {
    while (!maxHeap.isEmpty()) {
        const { iterations, coolingPeriodQueue } = execute(
            n,
            maxHeap,
            cpuIntervals,
        );

        reQueueCoolingPeriod(coolingPeriodQueue, maxHeap);

        if (!maxHeap.isEmpty()) cpuIntervals[0] += iterations;
    }

    return cpuIntervals[0];
};

const execute = (
    n,
    maxHeap,
    cpuIntervals,
    iterations = n + 1,
    coolingPeriodQueue = new Queue(),
) => {
    while (0 < iterations && !maxHeap.isEmpty()) {
        const frequency = maxHeap.dequeue().element;

        const hasFrequency = 0 < frequency - 1;
        if (hasFrequency) coolingPeriodQueue.enqueue(frequency - 1);

        cpuIntervals[0]++;
        iterations--;
    }

    return { iterations, coolingPeriodQueue };
};

const reQueueCoolingPeriod = (coolingPeriodQueue, maxHeap) => {
    while (!coolingPeriodQueue.isEmpty()) {
        maxHeap.enqueue(coolingPeriodQueue.dequeue());
    }
};

/**
 * https://leetcode.com/problems/task-scheduler/
 * Time O(N) | Space O(1)
 * @param {character[]} tasks
 * @param {number} n
 * @return {number}
 */
var leastInterval = function (tasks, n) {
    const frequencyMap = getFrequencyMap(tasks);
    const maxFrequency = getMaxFrequency(frequencyMap);
    const mostFrequentTask = getMostFrequentTask(frequencyMap, maxFrequency);
    const interval = (maxFrequency - 1) * (n + 1) + mostFrequentTask;

    return Math.max(tasks.length, interval);
};

var getFrequencyMap = (tasks, frequencyMap = new Array(26).fill(0)) => {
    for (const task of tasks) {
        const index = task.charCodeAt(0) - 'A'.charCodeAt(0);

        frequencyMap[index]++;
    }

    return frequencyMap;
};

const getMaxFrequency = (frequencyMap, maxFrequency = 0) => {
    for (const frequency of frequencyMap) {
        maxFrequency = Math.max(maxFrequency, frequency);
    }

    return maxFrequency;
};

const getMostFrequentTask = (
    frequencyMap,
    maxFrequency,
    mostFrequentTask = 0,
) => {
    for (const frequency of frequencyMap) {
        const isSame = frequency === maxFrequency;
        if (isSame) mostFrequentTask++;
    }

    return mostFrequentTask;
};

0355-design-twitter:
/**
 * https://leetcode.com/problems/design-twitter/
 * Your Twitter object will be instantiated and called as such:
 * var obj = new Twitter()
 * obj.postTweet(userId,tweetId)
 * var param_2 = obj.getNewsFeed(userId)
 * obj.follow(followerId,followeeId)
 * obj.unfollow(followerId,followeeId)
 */
class Twitter {
    constructor() {
        this.tweets = [];
        this.following = new Map();
    }

    postTweet(userId, tweetId, { tweets } = this) {
        tweets.push({ authorId: userId, id: tweetId });
    }

    getNewsFeed(userId, newsIDs = [], { tweets, following } = this) {
        for (let i = tweets.length - 1; 0 <= i && newsIDs.length < 10; i--) {
            const tweet = tweets[i];

            const isAuthor = tweet.authorId === userId;
            const isFollowing = following?.get(userId)?.has(tweet.authorId);
            const canAddTweet = isAuthor || isFollowing;
            if (canAddTweet) newsIDs.push(tweet.id);
        }

        return newsIDs;
    }

    follow(followerId, followeeId, { following } = this) {
        if (!following.has(followerId)) following.set(followerId, new Set());

        following.get(followerId).add(followeeId);
    }

    unfollow(followerId, followeeId, { following } = this) {
        if (following.has(followerId))
            following.get(followerId).delete(followeeId);
    }
}

2542-maximum-subsequence-score:
/**
 * MinPriorityQueue | Sorting
 * Time O(n*log(n)) | space O(n)
 * https://leetcode.com/problems/maximum-subsequence-score/
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @param {number} k
 * @return {number}
 */
var maxScore = function (nums1, nums2, k) {
    const minQ = new MinPriorityQueue({
        compare: (a, b) => {
            return a - b;
        },
    });

    let maxScore = 0;
    let runningTotal = 0;
    let takenElements = 0;

    const nums12 = nums1.map((num, idx) => {
        return [num, nums2[idx]];
    });

    nums12.sort((a, b) => {
        return b[1] - a[1];
    });

    for (let i = 0; i < nums12.length; i++) {
        const n1 = nums12[i][0];
        const n2 = nums12[i][1];

        runningTotal += n1;
        minQ.enqueue(n1);

        if (minQ.size() === k) {
            maxScore = Math.max(maxScore, runningTotal * n2);
        }
        if (minQ.size() > k) {
            runningTotal -= minQ.dequeue();
            maxScore = Math.max(maxScore, runningTotal * n2);
        }
    }

    return maxScore;
};

