0767-reorganize-string:
/**
 * MaxHeap | Hashing
 * Time O(n*log(n)) | Space O(n)
 * https://leetcode.com/problems/reorganize-string/
 * @param {string} s
 * @return {string}
 */
var reorganizeString = function (s) {
    const maxQ = new MaxPriorityQueue({
        compare: (a, b) => {
            return b[0] - a[0];
        },
    });

    const freq = {};
    for (let i = 0; i < s.length; i++) {
        const char = s[i];
        freq[char] = (freq[char] && freq[char] + 1) || 1;
    }
    for (const key in freq) {
        const val = freq[key];
        maxQ.enqueue([val, key]);
    }

    let orgStr = '';
    while (!maxQ.isEmpty()) {
        const [occurance, char] = maxQ.dequeue();

        if (orgStr[orgStr.length - 1] === char) {
            if (maxQ.isEmpty()) return '';

            const [occurance1, char1] = maxQ.dequeue();
            orgStr += char1;
            if (occurance1 - 1) {
                maxQ.enqueue([occurance1 - 1, char1]);
            }
            maxQ.enqueue([occurance, char]);
        } else {
            orgStr += char;
            if (occurance - 1) {
                maxQ.enqueue([occurance - 1, char]);
            }
        }
    }

    return orgStr;
};

1405-longest-happy-string:
/**
 * PriorityQueue
 * Time O(n*log(n)) | Space O(n)
 * https://leetcode.com/problems/longest-happy-string/
 * @param {number} a
 * @param {number} b
 * @param {number} c
 * @return {string}
 */
var longestDiverseString = function (a, b, c) {
    const maxQ = new MaxPriorityQueue({
        compare: (a, b) => {
            return b[0] - a[0];
        },
    });

    a && maxQ.enqueue([a, 'a']);
    b && maxQ.enqueue([b, 'b']);
    c && maxQ.enqueue([c, 'c']);

    let happyStr = '';

    while (!maxQ.isEmpty()) {
        let [count, char] = maxQ.dequeue();

        if (
            happyStr[happyStr.length - 1] === char &&
            happyStr[happyStr.length - 2] === char
        ) {
            if (!maxQ.isEmpty()) {
                let [count1, char1] = maxQ.dequeue();

                happyStr += char1;
                count1--;

                count1 && maxQ.enqueue([count1, char1]);
                maxQ.enqueue([count, char]);
            }
        } else {
            if (count >= 2) {
                happyStr += char.repeat(2);
                count -= 2;
            } else {
                happyStr += char;
                count--;
            }

            count && maxQ.enqueue([count, char]);
        }
    }

    return happyStr;
};

