/**
 * Brute Force - DFS
 * Time O(2^N) | Space O(N)
 * https://leetcode.com/problems/climbing-stairs/
 * @param {number} n
 * @return {number}
 */
var climbStairs = (n, index = 0) => {
    const isBaseCase1 = n < index;
    if (isBaseCase1) return 0;

    const isBaseCase2 = index === n;
    if (isBaseCase2) return 1;

    const [next, nextNext] = [index + 1, index + 2];
    const left = climbStairs(n, next); /* Time O(2^N) | Space O(N) */
    const right = climbStairs(n, nextNext); /* Time O(2^N) | Space O(N) */

    return left + right;
};

/**
 * DP - Top Down
 * Array - Memoization
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/climbing-stairs/
 * @param {number} n
 * @return {number}
 */
var climbStairs = (n, index = 0, memo = Array(n + 1).fill(0)) => {
    const isBaseCase1 = n < index;
    if (isBaseCase1) return 0;

    const isBaseCase2 = index === n;
    if (isBaseCase2) return 1;

    const hasSeen = memo[index] !== 0;
    if (hasSeen) return memo[index];

    const [next, nextNext] = [index + 1, index + 2];
    const left = climbStairs(n, next, memo); /* Time O(N) | Space O(N) */
    const right = climbStairs(n, nextNext, memo); /* Time O(N) | Space O(N) */

    memo[index] = left + right; /*           | Space O(N) */
    return memo[index];
};

/**
 * DP - Bottom Up
 * Array - Tabulation
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/climbing-stairs/
 * @param {number} n
 * @return {number}
 */
var climbStairs = (n) => {
    const isBaseCase = n === 1;
    if (isBaseCase) return 1;

    const tabu = initTabu(n); /* Space O(N) */

    search(n, tabu);

    return tabu[n];
};

var initTabu = (n) => {
    const tabu = new Array(n + 1).fill(0);

    tabu[1] = 1;
    tabu[2] = 2;

    return tabu;
};

var search = (n, tabu) => {
    for (let index = 3; index <= n; index++) {
        /* Time O(N) */
        const [prev, prevPrev] = [index - 1, index - 2];

        tabu[index] = tabu[prev] + tabu[prevPrev]; /* Space O(N) */
    }
};

/**
 * DP - Fibonacci Number
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/climbing-stairs/
 * @param {number} n
 * @return {number}
 */
var climbStairs = (n) => {
    const isBaseCase = n === 1;
    if (isBaseCase) return 1;

    let [next, nextNext] = [1, 2];

    for (let index = 3; index <= n; index++) {
        /* Time O(N) */
        const temp = next + nextNext;

        next = nextNext;
        nextNext = temp;
    }

    return nextNext;
};

/**
 * Matrix - Bitnets Method
 * Time O(log(N)) | Space O(1)
 * https://leetcode.com/problems/climbing-stairs/
 * @param {number} n
 * @return {number}
 */
var climbStairs = (n) => {
    const prev = [
        [1, 1],
        [1, 0],
    ];
    const next = power(n, prev); /* Time O(log(N)) */

    return next[0][0];
};

const power = (n, prev) => {
    let next = [
        [1, 0],
        [0, 1],
    ];

    const isEmpty = () => n === 0;
    while (!isEmpty()) {
        /* Time O(log(N)) */
        const isBit = (n & 1) === 1;
        if (isBit) next = multiply(next, prev); /* Time O(1) | Space O(1) */

        n >>= 1;
        prev = multiply(prev, prev); /* Time O(1) | Space O(1) */
    }

    return next;
};

const multiply = (prev, next) => {
    const [rows, cols] = [2, 2];
    const matrix = new Array(rows).fill().map(() => new Array(cols).fill(0));

    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            const left = prev[row][0] * next[0][col];
            const right = prev[row][1] * next[1][col];

            matrix[row][col] = left + right;
        }
    }

    return matrix;
};

/**
 * Math - Fibonacci Formula
 * Time O(log(N)) | Space O(1)
 * https://leetcode.com/problems/climbing-stairs/
 * @param {number} n
 * @return {number}
 */
var climbStairs = (n, sqrt5 = Math.sqrt(5)) => {
    const phi = (sqrt5 + 1) / 2;
    const psi = (sqrt5 - 1) / 2;

    const phiPow = Math.pow(phi, n + 1);
    const psiPow = Math.pow(psi, n + 1);

    return (phiPow - psiPow) / sqrt5;
};

0746-min-cost-climbing-stairs:
/**
 * DP - Top Down
 * Hash Map - Memoization
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/min-cost-climbing-stairs/
 * @param {number[]} cost
 * @return {number}
 */
var minCostClimbingStairs = (cost, i = cost.length, memo = new Map()) => {
    const isBaseCase = i <= 1;
    if (isBaseCase) return 0;

    if (memo.has(i)) return memo.get(i);

    const [prev, prevPrev] = [i - 1, i - 2];
    const downOne =
        minCostClimbingStairs(cost, prev, memo) +
        cost[prev]; /* Time O(N) | Space O(N) */
    const downTwo =
        minCostClimbingStairs(cost, prevPrev, memo) +
        cost[prevPrev]; /* Time O(N) | Space O(N) */

    memo.set(i, Math.min(downOne, downTwo));

    return memo.get(i);
};

/**
 * DP - Bottom Up
 * Array - Tabulation
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/min-cost-climbing-stairs/
 * @param {number[]} cost
 * @return {number}
 */
var minCostClimbingStairs = (cost) => {
    const tabu = new Array(cost.length + 1).fill(0);

    for (let i = 2; i < tabu.length; i++) {
        const [prev, prevPrev] = [i - 1, i - 2];
        const downOne = tabu[prev] + cost[prev];
        const downTwo = tabu[prevPrev] + cost[prevPrev];

        tabu[i] = Math.min(downOne, downTwo);
    }

    return tabu[tabu.length - 1];
};

/**
 * DP - Bottom Up
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/min-cost-climbing-stairs/
 * @param {number[]} cost
 * @return {number}
 */
var minCostClimbingStairs = (cost) => {
    let [downOne, downTwo] = [0, 0];

    for (let i = 2; i < cost.length + 1; i++) {
        /* Time O(N) */
        const temp = downOne;

        const [_prev, _prevPrev] = [i - 1, i - 2];
        const prev = downOne + cost[_prev];
        const prevPrev = downTwo + cost[_prevPrev];

        downOne = Math.min(prev, prevPrev);
        downTwo = temp;
    }

    return downOne;
};

0198-house-robber:
/**
 * Brute Force - DFS
 * Time O(2^N) | Space O(N)
 * https://leetcode.com/problems/house-robber/
 * @param {number[]} nums
 * @return {number}
 */
var rob = (nums, i = 0) => {
    const isBaseCase = nums <= i;
    if (isBaseCase) return 0;

    const [next, nextNext] = [i + 1, i + 2];
    const right = nums[i];
    const mid = rob(nums, next); /* Time O(2^N) | Space O(N) */
    const left = rob(nums, nextNext); /* Time O(2^N) | Space O(N) */
    const house = left + right;

    return Math.max(house, mid);
};

/**
 * DP - Top Down
 * Array - Memoization
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/house-robber/
 * @param {number[]} nums
 * @return {number}
 */
var rob = (nums, i = 0, memo = initMemo(nums)) => {
    const isBaseCase = nums.length <= i;
    if (isBaseCase) return 0;

    const hasSeen = 0 <= memo[i];
    if (hasSeen) return memo[i];

    const [next, nextNext] = [i + 1, i + 2];
    const right = nums[i];
    const mid = rob(nums, next, memo); /* Time O(N) | Space O(N) */
    const left = rob(nums, nextNext, memo); /* Time O(N) | Space O(N) */
    const house = left + right;

    memo[i] = Math.max(mid, house); /*           | Space O(N) */

    return memo[i];
};

const initMemo = (nums) => Array(nums.length + 1).fill(-1);

/**
 * DP - Bottom Up
 * Array - Tabulation
 * Time O(N) | Space O(N)
 * https://leetcode.com/problems/house-robber/
 * @param {number[]} nums
 * @return {number}
 */
var rob = (nums) => {
    if (!nums.length) return 0;

    const tabu = initTabu(nums);

    for (let i = 1; i < nums.length; i++) {
        /* Time O(N) */
        const right = nums[i];
        const mid = tabu[i];
        const left = tabu[i - 1];
        const house = left + right;

        tabu[i + 1] = Math.max(mid, house); /* Space O(N) */
    }

    return tabu[nums.length];
};

const initTabu = (nums) => {
    const tabu = Array(nums.length + 1).fill(0);

    tabu[1] = nums[0];

    return tabu;
};

/**
 * DP - Bottom Up
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/house-robber/
 * @param {number[]} nums
 * @return {number}
 */
var rob = (nums) => {
    if (!nums.length) return 0;

    let [left, mid] = [0, 0];

    for (const right of nums) {
        /* Time O(N) */
        const temp = mid;
        const house = left + right;

        mid = Math.max(mid, house);
        left = temp;
    }

    return mid;
};

