    const isBaseCase2 = index === 0 || subSetSum < 0;
    if (isBaseCase2) return false;

    const difference = subSetSum - nums[index - 1];

    const left = dfs(nums, index - 1, difference);
    const right = dfs(nums, index - 1, subSetSum);

    return left || right;
};

/**
