    const subSetSum = sum >> 1;
    const memo = initMemo(nums, subSetSum); /*               | Space O(N * M) */
    const index = nums.length - 1;

    return dfs(
        nums,
        index,
        subSetSum,
        memo,
    ); /* Time O(N * M) | Space O(N * M) */
};

var initMemo = (nums, subSetSum) =>
