 * @param {number} m
 * @param {number} n
 * @return {number}
 */
var uniquePaths = (row, col) => {
    const tabu = initTabu(col); /* Time O(COLS)        | Space O(COLS) */

    search(row, col, tabu); /* Time O(ROWS * COLS) | Space O(COLS) */

    return tabu[col - 1];
};

