    for (let col = (text2.length - 1); (0 <= col); col--) {/* Time O(N) */
        const temp = initTabu(text1);                               /* Space O(M) */

        for (let row = (text1.length - 1); (0 <= row); row--) {/* Time O(M) */
            const isEqual = (text1[row] == text2[col]);

            temp[row] = isEqual                                     /* Space O(M) */
                ? (tabu[(row + 1)] + 1)
                : Math.max(tabu[row], temp[(row + 1)]);
        }

        tabu = temp;                                                /* Space O(M) */
    }

    return tabu;
}

0309-best-time-to-buy-and-sell-stock-wit:
/**
 * Greedy - State Machine
 * Time O(N) | Space O(1)
 * https://leetcode.com/problems/best-time-to-buy-and-sell-stock-with-cooldown/
 * @param {number[]} prices
 * @return {number}
 */
var maxProfit = (prices) => {
    let [sold, held, reset] = [-Infinity, -Infinity, 0];

    [sold, reset] = search(prices, sold, held, reset); /* Time O(N) */

    return Math.max(sold, reset);
};

var search = (prices, sold, held, reset) => {
    for (const price of prices) {
        /* Time O(N) */
        const preSold = sold;

        sold = held + price;
        held = Math.max(held, reset - price);
        reset = Math.max(reset, preSold);
    }

    return [sold, reset];
};

/**
 * DP - Bottom Up
 * Array - Tabulation
 * Time O(N^2) | Space O(N)
 * https://leetcode.com/problems/best-time-to-buy-and-sell-stock-with-cooldown/
 * @param {number[]} prices
 * @return {number}
 */
var maxProfit = (prices) => {
    const tabu = initTabu(prices); /* Space O(N) */

    search(prices, tabu); /* Time O(N * N) */

    return tabu[0];
};

