    if (isLess)
        return change(amount, coins, n - 1); /* Time O(2^N) | Space O(N) */

    const left = change(
        amount - coins[n - 1],
        coins,
        n,
    ); /* Time O(2^N) | Space O(N) */
    const right = change(amount, coins, n - 1); /* Time O(2^N) | Space O(N) */

    return left + right;
};

/**
