    new Array((total + 1) << 1).fill(0); /* Time O(M) | Space O(M) */

var getTabu = (nums, total) => {
    const tabu = initTabu(total); /* Time O(M) | Space O(M) */
    const [left, right] = [total + nums[0], total - nums[0]];

    tabu[left] = 1; /*           | Space O(M) */
    tabu[right] += 1; /*           | Space O(M) */

    return tabu;
};

