    for (let i = 1; i < nums.length; i++) {
        /* Time O(N) */
        const num = nums[i];
        const temp = initTabu(total); /* Time O(M) | Space O(M) */

        tabu = update(num, total, tabu, temp); /* Time O(M) | Space O(M) */
    }

    return tabu;
};

var update = (num, total, tabu, temp) => {
    for (let sum = -total; sum <= total; sum++) {
