 * @param {number[]} cardPoints
 * @param {number} k
 * @return {number}
 */
var maxScore = function (cardPoints, k) {
    const total = cardPoints.reduce((acc, curr) => acc + curr, 0);
    let currTotal = cardPoints
        .slice(0, cardPoints.length - k)
        .reduce((acc, curr) => acc + curr, 0);
