 * https://leetcode.com/problems/powx-n/
 * @param {number} x
 * @param {number} n
 * @return {number}
 */
var myPow = (x, n) => {
    const isBaseCase1 = x === 1.0 || n === 0;
    if (isBaseCase1) return 1;

    const isBaseCase2 = n === 1;
    if (isBaseCase2) return x;

    const isEven = n % 2 === 0;
    if (isEven)
        return myPow(x * x, n / 2); /* Time O(log(N)) | Space O(log(N)) */

    const isOdd = n % 2 === 1;
    if (isOdd)
        return x * myPow(x, n - 1); /* Time O(log(N)) | Space O(log(N)) */

    return 1 / myPow(x, -n);
};

/**
 * DFS
 * Time (log(N)) | Space O(log(N))
 * https://leetcode.com/problems/powx-n/
 * @param {number} x
 * @param {number} n
 * @return {number}
 */
var myPow = (x, n) => {
    const isBaseCase = n === 0;
    if (isBaseCase) return 1;

    const abs = Math.abs(n);
    const isEven = abs % 2 === 0;

    const power = isEven
        ? myPow(x * x, abs / 2) /* Time O(log(N)) | Space O(log(N)) */
        : myPow(x * x, (abs - 1) / 2) *
          x; /* Time O(log(N)) | Space O(log(N)) */

    const isNegative = n < 0;

    return isNegative ? 1 / power : power;
};

