    const half = fastPow(x, n / 2); /* Time O(log(N)) | Space O(log(N)) */

    const isEven = n % 2 === 0;
    if (isEven) return half * half;

    const isOdd = n % 2 === 1;
    if (isOdd) return half * half * x;
};

/**
