/**
 * @param {Function} fn
 * @return {Function}
 */
function memoize(fn) {
    let memo = {};
    return function (...args) {
        let argsjson = JSON.stringify(args);
        if (memo.hasOwnProperty(argsjson)) return memo[argsjson];
        return (memo[argsjson] = fn(...args));
    };
}

